const s = params.size;
const n = params.branches;
const baseY = s * 0.14;
const coralMat = { preset: 'stone', color: params.color, roughness: 0.72, flatShading: true };
const tipColor = api.mix(params.color, '#ffd1a6', 0.34);
const tipMat = { preset: 'stone', color: tipColor, roughness: 0.68, flatShading: true };
const fanColor = api.mix(params.color, '#9b35d1', 0.42);
const fanMat = { preset: 'stone', color: fanColor, roughness: 0.76, flatShading: true };
const rockMat = { preset: 'stone', color: '#6f756d', roughness: 0.95, flatShading: true };
const sandMat = { preset: 'sand', color: '#c9aa72', roughness: 1, flatShading: true };
api.add(api.cylinder(s * 0.42, s * 0.5, s * 0.08, 18).translate(0, s * 0.04, 0), sandMat);
const rock = api.icosphereRock(s * 0.34, 0.62).scale(1.35, 0.58, 1.05).translate(0, baseY, 0);
rock.vertexColor((x, y, z) => api.mix('#4f5650', '#8d8c78', 0.45 + 0.25 * api.noise3(x * 5, y * 5, z * 5)));
api.add(rock, rockMat);
for (let i = 0; i < n; i++) {
  const a = i * Math.PI * 2 / n + (api.rng() - 0.5) * 0.28;
  const radial = s * (0.08 + api.rng() * 0.14);
  const x0 = Math.cos(a) * radial;
  const z0 = Math.sin(a) * radial;
  const lean = s * (0.17 + api.rng() * 0.18);
  const h = s * (0.42 + api.rng() * 0.28);
  const bend = (api.rng() - 0.5) * s * 0.12;
  const px = -Math.sin(a);
  const pz = Math.cos(a);
  const p0 = [x0, baseY + s * 0.03, z0];
  const p1 = [x0 + Math.cos(a) * lean * 0.34 + px * bend, baseY + h * 0.32, z0 + Math.sin(a) * lean * 0.34 + pz * bend];
  const p2 = [x0 + Math.cos(a) * lean * 0.68 - px * bend * 0.3, baseY + h * 0.69, z0 + Math.sin(a) * lean * 0.68 - pz * bend * 0.3];
  const p3 = [x0 + Math.cos(a) * lean, baseY + h, z0 + Math.sin(a) * lean];
  const rad = s * (0.035 + api.rng() * 0.012);
  api.add(api.tube([p0, p1, p2, p3], rad, 7), coralMat);
  const split = i % 2 === 0 || api.rng() > 0.55;
  if (split) {
    const side = api.rng() > 0.5 ? 1 : -1;
    const q1 = [p2[0] + px * side * s * 0.11, p2[1] + s * 0.12, p2[2] + pz * side * s * 0.11];
    const q2 = [p2[0] + px * side * s * 0.2 + Math.cos(a) * s * 0.04, p2[1] + s * 0.25, p2[2] + pz * side * s * 0.2 + Math.sin(a) * s * 0.04];
    api.add(api.tube([p2, q1, q2], rad * 0.72, 7), coralMat);
    api.add(api.icosphereRock(rad * 1.35, 0.28).translate(q2[0], q2[1], q2[2]), tipMat);
  }
  api.add(api.icosphereRock(rad * 1.5, 0.3).translate(p3[0], p3[1], p3[2]), tipMat);
  for (let k = 1; k < 3; k++) {
    const t = k / 3;
    const bx = p1[0] * (1 - t) + p3[0] * t;
    const by = p1[1] * (1 - t) + p3[1] * t;
    const bz = p1[2] * (1 - t) + p3[2] * t;
    api.add(api.icosphereRock(rad * 1.18, 0.35).translate(bx, by, bz), tipMat);
  }
}
for (let f = 0; f < 3; f++) {
  const ang = (f * 120 + 35) * Math.PI / 180;
  const ux = Math.cos(ang);
  const uz = Math.sin(ang);
  const vx = -uz;
  const vz = ux;
  const cx = ux * s * 0.13;
  const cz = uz * s * 0.13;
  const y0 = baseY + s * 0.04;
  const nodes = [];
  for (let row = 0; row < 5; row++) {
    const yy = y0 + row * s * 0.115;
    const half = s * (0.04 + row * 0.045);
    const count = row + 2;
    nodes[row] = [];
    for (let j = 0; j < count; j++) {
      const u = -half + 2 * half * j / (count - 1);
      nodes[row][j] = [cx + vx * u, yy, cz + vz * u];
      if (row > 0) {
        const parentIndex = Math.min(Math.floor(j * (nodes[row - 1].length - 1) / (count - 1)), nodes[row - 1].length - 1);
        const parent = nodes[row - 1][parentIndex];
        api.add(api.tube([parent, nodes[row][j]], s * 0.012, 5), fanMat);
      }
      if (j > 0) api.add(api.tube([nodes[row][j - 1], nodes[row][j]], s * 0.009, 5), fanMat);
    }
  }
  const top = nodes[4];
  for (let j = 0; j < top.length; j++) api.add(api.icosphereRock(s * 0.022, 0.25).translate(top[j][0], top[j][1], top[j][2]), tipMat);
}
api.collider({ kind: 'cylinder', radius: s * 0.5, halfHeight: s * 0.07, offset: [0, s * 0.07, 0] });
api.collider({ kind: 'capsule', radius: s * 0.3, halfHeight: s * 0.32, offset: [0, baseY + s * 0.32, 0] });
return api.build();
